(()=>{'use strict';const config=window.FENEK_CONFIG||{},id=Number(config.metrikaId);let ready=false;const allowed=new Set(['lead_open','lead_start','lead_submit','lead_success','payment_lead_success','cargo_lead_success','lead_error','telegram_click','max_click','cargo_calculate','exchange_select']);const trackingKeys=['utm_source','utm_medium','utm_campaign','utm_content','utm_term','yclid'];function storageGet(key){try{return sessionStorage.getItem(key)}catch{return null}}function storageSet(key,value){try{sessionStorage.setItem(key,value)}catch{}}let attribution={};try{attribution=JSON.parse(storageGet('fenek_attribution')||'{}')}catch{}const params=new URLSearchParams(location.search);if(trackingKeys.some(k=>params.has(k))){attribution={landing:location.pathname};trackingKeys.forEach(k=>{if(params.has(k))attribution[k]=params.get(k).slice(0,250)});storageSet('fenek_attribution',JSON.stringify(attribution))}window.FenekAnalytics={attribution,goal(name,params={}){if(!allowed.has(name))return;const clean={};['form','page','service','reason','transport'].forEach(k=>{if(params[k]!==undefined)clean[k]=String(params[k]).slice(0,80)});document.dispatchEvent(new CustomEvent('fenek:goal',{detail:{name,params:clean}}));if(ready)window.ym(id,'reachGoal',name,clean)}};function start(){if(ready||!Number.isSafeInteger(id)||id<=0)return;window.ym=window.ym||function(){(window.ym.a=window.ym.a||[]).push(arguments)};window.ym.l=Date.now();const script=document.createElement('script');script.async=true;script.src='https://mc.yandex.ru/metrika/tag.js?id='+encodeURIComponent(id);document.head.append(script);window.ym(id,'init',{ssr:true,clickmap:true,ecommerce:'dataLayer',referrer:document.referrer,url:location.href,accurateTrackBounce:true,trackLinks:true,webvisor:true,trackHash:false});ready=true}start();document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(!a)return;try{const url=new URL(a.href);if(url.hostname==='t.me')window.FenekAnalytics.goal('telegram_click',{page:location.pathname});if(url.hostname==='max.ru')window.FenekAnalytics.goal('max_click',{page:location.pathname})}catch{}})})();
